    "content": "个人网站即我的世界 过去我是个喜欢折腾网站的人，但模板换了又换，总感觉被什么东西困住了。 受我的世界、黑客帝国和元宇宙的启发，借助 AI ，我把个人网站从二维网页建成了三维世界。 这个世界包罗万象，可以自由移动，里面建了篮球场，健身房，工作台，甚至还有昼夜交替和天气系统。 对于二维网页也完全可以内嵌进来，例如按 F 查看。而且得益于方块风的性能开销小，手机也能轻松访问。 逛上一圈，像是去朋友家做客了一趟。比起传统的网站，这样的相识或许更让人印象深刻。 一旦接受了这个设定，就再也回不去传统个人网站了… 实机截图 🔗…"
