    "description": "2026年10月30日 我是一名大专毕业生，也是一名网文作家。玄幻、都市等“大众文”我写，扶贫、支教等现实题材我也写。 很多人都有过“作家梦”。大学时，我看了不少网文，心里冒出一个念头：我是不是也能写？说干就干，白天上课，晚上挑灯码字。第一稿被拒，第二稿被拒，第三次终于签上“分成约”。9个月时间，写完了第一本书，稿费4000多元，万丈雄心折了大半。 写作，不是靠字数堆出来的。写了上百万字后，我真真切切体会到这个道理。我能感觉到，自己打心…",
    "content": "2026年10月30日 我是一名大专毕业生，也是一名网文作家。玄幻、都市等“大众文”我写，扶贫、支教等现实题材我也写。 很多人都有过“作家梦”。大学时，我看了不少网文，心里冒出一个念头：我是不是也能写？说干就干，白天上课，晚上挑灯码字。第一稿被拒，第二稿被拒，第三次终于签上“分成约”。9个月时间，写完了第一本书，稿费4000多元，万丈雄心折了大半。 写作，不是靠字数堆出来的。写了上百万字后，我真真切切体会到这个道理。我能感觉到，自己打心底喜欢写作。那时候，在很多人眼里，网络作家甚至算不上正经职业。不转行，就只能用作…"
