    "content": "2026年10月30日 新华社香港10月29日电&nbsp;&nbsp;香港特区政府29日公布独立委员会就大埔宏福苑火灾提交的报告，香港特区行政长官李家超率特区政府相关官员当日下午召开记者会，宣布问责事宜及改革措施。 记者会上，李家超率特区政府相关官员就宏福苑火灾向公众道歉，表示特区政府将依法对涉案人员及相关公司进行刑事追责，对有关公务员的不足和缺失进行调查，决定有关主要官员承担政治责任。 李家超表示，特区政府将以独立委员会报告为基础进行全面改革，包括禁止及打击楼宇维修工程围标、成立跨部门特遣队打击楼宇维修工程围标…"
